#include <algorithm>
#include <array>
#include <chrono>
#include <cctype>
#include <cmath>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <set>
#include <sstream>
#include <stdexcept>
#include <string>
#include <unordered_map>
#include <vector>
namespace fs = std::filesystem;
struct Row {std::string source,bridge,target,evidence,status;int score=0;};
static std::vector<std::string> csv(const std::string& s){std::vector<std::string> out;std::string part;bool in=false;for(size_t i=0;i<s.size();++i){char c=s[i];if(c=='"'){if(in&&i+1<s.size()&&s[i+1]=='"'){part+='"';++i;}else in=!in;}else if(c==','&&!in){out.push_back(part);part.clear();}else part+=c;}if(in)throw std::runtime_error("Malformed quoted CSV record");if(!part.empty()&&part.back()=='\r')part.pop_back();out.push_back(part);return out;}
static std::string escape(const std::string& s){std::string x="\"";for(char c:s){if(c=='"')x+='"';if(c=='\n'||c=='\r')x+=' ';else x+=c;}return x+'"';}
static std::vector<Row> read(const fs::path& file){std::ifstream f(file,std::ios::binary);if(!f)throw std::runtime_error("Missing paths.csv: "+file.string());std::string l;std::getline(f,l);auto h=csv(l);if(h.size()!=6||h[0]!="source"||h[1]!="bridge"||h[2]!="target")throw std::runtime_error("Unexpected v10 CSV header");std::vector<Row> r;while(std::getline(f,l)){if(l.empty()||l=="\r")continue;auto v=csv(l);if(v.size()!=6)throw std::runtime_error("Malformed paths.csv row");Row x;x.source=v[0];x.bridge=v[1];x.target=v[2];x.score=std::stoi(v[3]);x.evidence=v[4];x.status=v[5];r.push_back(std::move(x));}return r;}
static std::uint32_t step(std::uint32_t s,std::uint32_t x,int family){switch(family){case 0:return (s+x*3u)%65521u;case 1:return (s*17u+x)%65521u;case 2:return (s^x)%65521u;case 3:return (s+x)%65521u;default:return (s*s+x)%65521u;}}
struct Metrics{size_t distinct=0,collisions=0,changed=0;double avgDiff=0,nsPerItem=0,binChi=0;};
static Metrics measure(int family,int seed){constexpr int N=4096;std::array<int,32> bins{};std::set<std::uint32_t> unique;std::uint32_t s=0,reference=0;double diff=0;size_t changed=0;volatile std::uint32_t sink=0;const auto begin=std::chrono::steady_clock::now();for(int i=0;i<N;++i){auto input=static_cast<std::uint32_t>((i*37+seed*101)%65521);s=step(s,input,family);reference=step(reference,input,3);unique.insert(s);++bins[std::min<size_t>(31,static_cast<size_t>(s)*32u/65521u)];if(s!=reference)++changed;diff+=std::abs(static_cast<double>(s)-static_cast<double>(reference));sink=s;}const auto end=std::chrono::steady_clock::now();(void)sink;Metrics m;m.distinct=unique.size();m.collisions=N-unique.size();m.changed=changed;m.avgDiff=diff/N;m.nsPerItem=std::chrono::duration<double,std::nano>(end-begin).count()/N;for(int b:bins){double d=static_cast<double>(b)-N/32.0;m.binChi+=d*d/(N/32.0);}return m;}
static bool leanName(const std::string& s){if(s.empty()||s.size()>240)return false;for(unsigned char c:s)if(!(std::isalnum(c)||c=='_'||c=='.'||c>=128))return false;return s.front()!='.'&&s.back()!='.';}
static void run(const fs::path& dir,int limit){auto rows=read(dir/"paths.csv");if(limit<1||limit>1000)throw std::runtime_error("Max path audit must be 1..1000");std::unordered_map<std::string,int> signatures;std::set<std::string> unorderedTriples;size_t undirectedDuplicates=0;for(const auto& r:rows){++signatures[r.evidence];std::array<std::string,3> names{r.source,r.bridge,r.target};std::sort(names.begin(),names.end());std::string key=names[0]+"\t"+names[1]+"\t"+names[2];if(!unorderedTriples.insert(key).second)++undirectedDuplicates;}
 std::unordered_map<size_t,int> testedFamilies;
 {std::ifstream previous(dir/"evaluation.csv");std::string line;if(previous){std::getline(previous,line);while(std::getline(previous,line)){auto fields=csv(line);if(fields.size()>=3){try{const size_t index=static_cast<size_t>(std::stoull(fields[1]));const int family=std::stoi(fields[2]);if(family>=0&&family<=4)testedFamilies[index]=family;}catch(const std::exception&){}}}}}
 fs::create_directories(dir/"audit_v11");const auto out=dir/"audit_v11";std::ofstream scores(out/"algorithm_metrics.csv");scores<<"path_index,source,bridge,target,evidence,repeat_count,family,distinct,collisions,changed_vs_reference,mean_abs_distance,chi_square_32,ns_per_item,verdict\n";std::set<std::string> emitted;std::ofstream probe(out/"LeanDeclarationsToCheck.lean");probe<<"-- v11 optional name-resolution probe. #check is NOT a proof of a relationship.\n";probe<<"-- Add correct `import Module.Name` statements in the isolated Lean workspace.\n";int tested=0,probed=0;for(size_t i=0;i<rows.size()&&tested<limit;++i){const auto& r=rows[i];if(r.evidence.empty()||r.source==r.target)continue;auto selected=testedFamilies.find(i);if(selected==testedFamilies.end())continue;const int family=selected->second;auto m=measure(family,73);std::string verdict=(m.collisions==0?"DIVERSE_SYNTHETIC_ONLY":"COLLISIONS_SYNTHETIC_ONLY");scores<<i<<','<<escape(r.source)<<','<<escape(r.bridge)<<','<<escape(r.target)<<','<<escape(r.evidence)<<','<<signatures[r.evidence]<<','<<family<<','<<m.distinct<<','<<m.collisions<<','<<m.changed<<','<<std::setprecision(12)<<m.avgDiff<<','<<m.binChi<<','<<m.nsPerItem<<','<<verdict<<'\n';for(const auto& name:{r.source,r.bridge,r.target})if(leanName(name)&&emitted.insert(name).second&&probed<150){probe<<"#check "<<name<<'\n';++probed;}++tested;}
 std::ofstream report(out/"AUDIT_REPORT.md");report<<"# MathResearchEngine v11 – Multi-Relation Evidence Audit\n\n"<<"- Original v10 path rows: "<<rows.size()<<"\n- Audited path hypotheses: "<<tested<<"\n- Repeated unordered node triples: "<<undirectedDuplicates<<"\n- Distinct structural evidence signatures: "<<signatures.size()<<"\n- Lean declaration names proposed for manual workspace resolution: "<<probed<<"\n\n"<<"## Scientific interpretation\n\n**No path has been formally proved.** A `#check` command, when run in a prepared Lean workspace, can confirm that a *name resolves and has a type*, not that A–B–C is mathematically composable. No automatic Lean execution is claimed.\n\n"<<"The numerical diagnostic measures output diversity, collisions, deviation from a fixed recurrence, a 32-bin distribution statistic and wall-clock execution time on a synthetic stream. They are NOT measurements of usefulness, correctness for an external task or novelty. The timing includes set bookkeeping, so it is NOT a pure kernel benchmark.\n\n"<<"The audit uses only the families actually recorded for generated applications in `evaluation.csv`; paths without generated applications are not benchmarked. Paths are filtered and ranked here only for research inspection; the original unfiltered `paths.csv` is preserved. Duplicate evidence and repeated triples expose possible inflation of apparent discovery counts.\n";
 if(!scores||!probe||!report)throw std::runtime_error("Writing v11 audit outputs failed");
 std::cout<<"V11_AUDIT_PASS paths="<<rows.size()<<" audited="<<tested<<" evidence_signatures="<<signatures.size()<<" triplet_repeats="<<undirectedDuplicates<<" lean_names="<<probed<<" output="<<out.string()<<'\n';}
int main(int argc,char**argv){try{if(argc==2&&std::string(argv[1])=="selftest"){auto v=csv("\"A,B\",C,\"D\"\"E\"");if(v.size()!=3||v[0]!="A,B"||v[2]!="D\"E"||step(0,1,1)!=1u||!leanName("Nat.add")||leanName("Nat;bad"))throw std::runtime_error("selftest failed");std::cout<<"V11_AUDIT_SELFTEST PASS\n";return 0;}if(argc<2||argc>3)throw std::runtime_error("usage: math_research_audit <v10-run-directory> [max-paths=100]");run(argv[1],argc==3?std::stoi(argv[2]):100);return 0;}catch(const std::exception& e){std::cerr<<"V11_AUDIT_ERROR "<<e.what()<<'\n';return 1;}}
